//! Port of `com.healthmarketscience.jackcess.impl.JetFormat` and
//! `com.healthmarketscience.jackcess.Database.FileFormat`.

use crate::bytebuf::ByteOrder;
use crate::datatype::DataType;

/// The `Database.FileFormat` enum.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FileFormat {
    V1997,
    GenericJet4,
    V2000,
    V2003,
    V2007,
    V2010,
    V2016,
    V2019,
    Msisam,
}

impl FileFormat {
    pub fn extension(self) -> &'static str {
        match self {
            FileFormat::V1997 | FileFormat::GenericJet4 | FileFormat::V2000 | FileFormat::V2003 => {
                ".mdb"
            }
            FileFormat::V2007 | FileFormat::V2010 | FileFormat::V2016 | FileFormat::V2019 => {
                ".accdb"
            }
            FileFormat::Msisam => ".mny",
        }
    }

    pub fn from_name(name: &str) -> Option<FileFormat> {
        match name.to_ascii_uppercase().as_str() {
            "V1997" => Some(FileFormat::V1997),
            "GENERIC_JET4" => Some(FileFormat::GenericJet4),
            "V2000" => Some(FileFormat::V2000),
            "V2003" => Some(FileFormat::V2003),
            "V2007" => Some(FileFormat::V2007),
            "V2010" => Some(FileFormat::V2010),
            "V2016" => Some(FileFormat::V2016),
            "V2019" => Some(FileFormat::V2019),
            "MSISAM" => Some(FileFormat::Msisam),
            _ => None,
        }
    }
}

/// Text encoding used by a format.  The Java library uses `java.nio.charset`
/// charsets; for Jet4/Ace text is stored as UTF-16LE.  Jet3 uses the code page
/// from the database header.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Charset {
    Utf16Le,
    Utf8,
    /// Windows-1252, the usual Jet3 code page and the default of the western
    /// Access versions.  It keeps its own variant (rather than being a
    /// [`Charset::SingleByte`]) because that is the name the existing callers
    /// and tests use; its mapping is the generated windows-1252 table, i.e.
    /// exactly the JDK's windows-1252 charset.
    Cp1252,
    /// Any other single byte code page the JDK resolves for a Jet 3 header,
    /// i.e. the windows, ISO-8859, DOS and IBM/EBCDIC pages.  The value is the
    /// code page number; `for_code_page` is the only constructor and the
    /// generated table holds the exact JDK decode/encode mapping.
    SingleByte(u16),
    /// A multi byte East Asian code page (932/936/949/950), implemented with
    /// the WHATWG encodings of `encoding_rs` plus the generated corrections
    /// which make them agree with the JDK charsets (see `MultiTable`).  The
    /// value is the code page number.
    MultiByte(u16),
    /// An IBM DBCS page (the EBCDIC ones like 930/939, the plain double byte
    /// ones like 942/1381 and the EUC-TW style 964).  Their exact JDK tables
    /// are generated by `java-src/CodePageGen.java bin` into
    /// `resources/format_ref/cp_dbcs.bin`; the decoder and encoder state
    /// machines are the `DbcsPage` implementation below.  The value is the
    /// code page number.
    Dbcs(u16),
}

impl Charset {
    /// `DatabaseImpl.getCodePageCharset`: the charset named by the windows
    /// code page in a Jet3 file header, or `None` when the code page is unset
    /// (or names no charset the JDK has).
    ///
    /// Java probes `windows-<cp>`, `cp<cp>` and `x-windows-<cp>` against the
    /// JVM's charset registry.  This port reproduces the result of that probe
    /// for every single byte page the JDK resolves (the generated
    /// `SINGLE_BYTE_TABLES`, driven by `java-src/CodePageGen.java`) and for
    /// every multi byte page a Jet 3 header can name: the four East Asian
    /// pages Jet 3 databases use (932/936/949/950, implemented with
    /// `encoding_rs` plus the JDK corrections) and the IBM DBCS pages (300,
    /// 834, 930, 933, 935, 937, 939, 942, 943, 948, 964, 970, 1364, 1381,
    /// 1383) with their exact JDK tables.
    ///
    /// A page which neither the generated tables nor the East Asian decoders
    /// cover (the ISO-2022-JP pages, which a Jet 3 header cannot name anyway)
    /// yields `None`, which is also what Java's probe yields; Java then falls
    /// back to the format charset.
    pub fn for_code_page(code_page: i16) -> Option<Charset> {
        if code_page <= 0 {
            return None;
        }
        let page = code_page as u16;
        // windows-1252 keeps its own variant (see the enum)
        if page == 1252 {
            return Some(Charset::Cp1252);
        }
        if single_byte_table(page).is_some() {
            return Some(Charset::SingleByte(page));
        }
        match page {
            932 | 936 | 949 | 950 => Some(Charset::MultiByte(page)),
            _ => {
                if dbcs_table(page).is_some() {
                    Some(Charset::Dbcs(page))
                } else {
                    None
                }
            }
        }
    }

    /// The Java charset name, as `Charset.name()` reports it.
    pub fn name(self) -> &'static str {
        match self {
            Charset::Utf16Le => "UTF-16LE",
            Charset::Utf8 => "UTF-8",
            Charset::Cp1252 => "windows-1252",
            Charset::SingleByte(page) => {
                single_byte_table(page)
                    .expect("single byte charset without table")
                    .name
            }
            Charset::MultiByte(page) => multi_byte_name(page),
            Charset::Dbcs(page) => dbcs_table(page).expect("dbcs charset without table").name,
        }
    }

    /// `true` for the code pages which are a multi byte encoding.  This is the
    /// set the JDK resolves; this port decodes all of them (932/936/949/950
    /// through `encoding_rs` with the JDK corrections, the other 15 through
    /// the generated tables).
    /// A Jet 3 header stores the code page in a signed short, so the code
    /// pages above 32767 (50220/50221/33722) can never name a charset there
    /// and are not included.
    pub fn is_multibyte_code_page(code_page: i16) -> bool {
        if code_page <= 0 {
            return false;
        }
        matches!(
            code_page,
            300 | 834
                | 930
                | 932
                | 933
                | 935
                | 936
                | 937
                | 939
                | 942
                | 943
                | 948
                | 949
                | 950
                | 964
                | 970
                | 1364
                | 1381
                | 1383
        )
    }

    /// `Charset.encode(String)` as jackcess uses it for the database password
    /// field: the raw bytes the charset produces for the string, with no BOM
    /// and no terminator.  Like Java's `Charset.encode(CharBuffer)`, a
    /// character the charset cannot represent (or a supplementary character)
    /// becomes the single replacement byte `?` (`0x3F`, `CodingErrorAction`'s
    /// default replacement).
    pub fn encode(self, s: &str) -> Vec<u8> {
        match self {
            Charset::Utf16Le => {
                let mut out = Vec::with_capacity(s.len() * 2);
                for u in s.encode_utf16() {
                    out.extend_from_slice(&u.to_le_bytes());
                }
                out
            }
            Charset::Utf8 => s.as_bytes().to_vec(),
            Charset::Cp1252 => encode_single_byte(1252, s),
            Charset::SingleByte(page) => encode_single_byte(page, s),
            Charset::MultiByte(page) => encode_multi_byte(page, s),
            Charset::Dbcs(page) => encode_dbcs(page, s),
        }
    }

    /// `Charset.decode(ByteBuffer)`: the UTF-16 code units of the string
    /// Java's `new String(bytes, charset)` produces, with malformed input
    /// replaced by U+FFFD.
    pub fn decode(self, bytes: &[u8]) -> Vec<u16> {
        match self {
            Charset::Utf16Le => {
                // decode UTF-16LE into UTF-16 code units ("UTF-16LE, no BOM")
                let mut out = Vec::with_capacity(bytes.len() / 2);
                let mut i = 0;
                while i + 1 < bytes.len() {
                    out.push(u16::from_le_bytes([bytes[i], bytes[i + 1]]));
                    i += 2;
                }
                out
            }
            Charset::Utf8 => String::from_utf8_lossy(bytes).encode_utf16().collect(),
            Charset::Cp1252 => decode_single_byte(1252, bytes),
            Charset::SingleByte(page) => decode_single_byte(page, bytes),
            Charset::MultiByte(page) => decode_multi_byte(page, bytes),
            Charset::Dbcs(page) => decode_dbcs(page, bytes),
        }
    }
}

// ---------------------------------------------------------------------------
// single byte code pages
// ---------------------------------------------------------------------------

/// One single byte code page: the exact JDK decode table plus the encoder
/// mappings which differ from the default "lowest byte of the decode table"
/// rule.  The JDK encoders have aliases no byte decodes to (the DOS/IBM pages
/// accept several code points per byte) and encode U+FFFD as `?` even when a
/// byte decodes to it, so the default rule alone is not exact.
struct CpTable {
    page: u16,
    name: &'static str,
    /// the UTF-16 unit byte `b` decodes to, indexed by `b`
    decode: [u16; 256],
    /// encoder overrides, sorted by unit
    extra_enc: &'static [(u16, u8)],
}

impl CpTable {
    /// `CharsetEncoder` for this page: an override if the JDK has one, else
    /// the lowest byte the unit decodes from, else the replacement byte.
    fn encode_unit(&self, unit: u16) -> u8 {
        if let Ok(i) = self.extra_enc.binary_search_by_key(&unit, |&(u, _)| u) {
            return self.extra_enc[i].1;
        }
        match self.decode.iter().position(|&u| u == unit) {
            Some(i) => i as u8,
            None => b'?',
        }
    }
}

/// The generated table of every single byte code page the JDK resolves through
/// `windows-<cp>` / `cp<cp>` / `x-windows-<cp>` (the probe
/// `DatabaseImpl.getCodePageCharset` uses).  Sorted by page number.
fn single_byte_table(page: u16) -> Option<&'static CpTable> {
    SINGLE_BYTE_TABLES
        .binary_search_by_key(&page, |t| t.page)
        .ok()
        .map(|i| &SINGLE_BYTE_TABLES[i])
}

fn decode_single_byte(page: u16, bytes: &[u8]) -> Vec<u16> {
    let table = single_byte_table(page).expect("single byte charset without table");
    bytes.iter().map(|&b| table.decode[b as usize]).collect()
}

fn encode_single_byte(page: u16, s: &str) -> Vec<u8> {
    let table = single_byte_table(page).expect("single byte charset without table");
    let mut out = Vec::with_capacity(s.len());
    for ch in s.chars() {
        let unit = ch as u32;
        out.push(if unit <= 0xFFFF {
            table.encode_unit(unit as u16)
        } else {
            b'?'
        });
    }
    out
}

// ---------------------------------------------------------------------------
// multi byte code pages
// ---------------------------------------------------------------------------

fn multi_byte_name(page: u16) -> &'static str {
    match page {
        932 => "windows-31j",
        936 => "GBK",
        949 => "x-windows-949",
        950 => "x-windows-950",
        _ => "unknown",
    }
}

/// The WHATWG encoding which corresponds to the code page.  The JDK's charset
/// for these pages is the Microsoft one, which is what the WHATWG encodings
/// were derived from; the mappings where they differ are corrected by the
/// generated [`MultiTable`].
fn multi_byte_encoding(page: u16) -> &'static encoding_rs::Encoding {
    match page {
        932 => encoding_rs::SHIFT_JIS,
        936 => encoding_rs::GBK,
        949 => encoding_rs::EUC_KR,
        950 => encoding_rs::BIG5,
        _ => panic!("code page {} has no multi byte encoding", page),
    }
}

fn multi_table(page: u16) -> &'static MultiTable {
    MULTI_TABLES
        .iter()
        .find(|t| t.page == page)
        .expect("multi byte charset without table")
}

/// One multi byte code page.  The JDK decodes these with a `char[256]` single
/// byte table (`b2cSB`), a per-lead double byte table (`b2c`) and the
/// `DoubleByte.Decoder` invalid input rules; the generated data here is the
/// JDK's single byte table, its lead byte set, and the corrections which turn
/// the WHATWG encoding into the JDK charset (the JDK pages decode CP932 user
/// defined characters, Big5 HKSCS pointers, ... differently).
struct MultiTable {
    page: u16,
    /// the JDK `b2cSB` table; U+FFFD means the byte starts a double byte char
    /// or is not mapped at all
    single: [u16; 256],
    /// one bit per byte: the JDK `b2c[b] != B2C_UNMAPPABLE` lead byte set
    lead_mask: [bool; 256],
    /// `(key << 16) | unit` for the pairs whose JDK decode differs from the
    /// WHATWG one; a unit of `0xFFFF` marks a pair the JDK has no mapping for
    /// while WHATWG does.  Sorted by key.
    pair_fix: &'static [u32],
    /// encoded as `unit << 48 | len << 40 | bytes` (big endian bytes), for the
    /// units whose JDK encoding differs from the WHATWG one.  Sorted by unit.
    enc_fix: &'static [u64],
}

impl MultiTable {
    fn is_lead(&self, byte: u8) -> bool {
        self.lead_mask[byte as usize]
    }

    /// `Some(unit)` for a pair the JDK decodes, `Some(None)` when the JDK has
    /// no mapping for it.
    fn pair_fix(&self, key: u16) -> Option<Option<u16>> {
        let i = self
            .pair_fix
            .binary_search_by_key(&key, |&packed| (packed >> 16) as u16)
            .ok()?;
        let unit = self.pair_fix[i] as u16;
        Some(if unit == 0xFFFF { None } else { Some(unit) })
    }

    /// The JDK bytes for a unit which the WHATWG encoding does not produce.
    fn enc_fix(&self, unit: u16) -> Option<([u8; 4], usize)> {
        let i = self
            .enc_fix
            .binary_search_by_key(&unit, |&packed| (packed >> 48) as u16)
            .ok()?;
        let packed = self.enc_fix[i];
        let len = ((packed >> 40) & 0xFF) as usize;
        let mut bytes = [0u8; 4];
        for (k, byte) in bytes.iter_mut().enumerate() {
            *byte = ((packed >> (24 - 8 * k)) & 0xFF) as u8;
        }
        Some((bytes, len))
    }

    /// The JDK's decode of one double byte unit, or `None` for a pair the JDK
    /// has no mapping for.  The WHATWG encoding of the pair is the fallback
    /// for the pairs both agree on.
    fn decode_pair(&self, b1: u8, b2: u8) -> Option<u16> {
        let key = ((b1 as u16) << 8) | b2 as u16;
        if let Some(fix) = self.pair_fix(key) {
            return fix;
        }
        if !self.is_lead(b1) {
            return None;
        }
        let encoding = multi_byte_encoding(self.page);
        let bytes = [b1, b2];
        let (text, had_errors) = encoding.decode_without_bom_handling(&bytes);
        if had_errors {
            return None;
        }
        let mut units = text.encode_utf16();
        match (units.next(), units.next()) {
            (Some(unit), None) => Some(unit),
            _ => None,
        }
    }
}

/// `DoubleByte.Decoder` of the JDK, which is what `new String(bytes, cs)`
/// uses: a single byte char is decoded directly, a byte whose `b2cSB` entry is
/// unmappable starts a double byte char, and a failed double byte char is a
/// malformed unit of length 1 (the lead byte only, the trail byte is decoded
/// again) unless the trail byte is neither a lead nor a single byte char, in
/// which case the whole pair is one unmappable unit.
fn decode_multi_byte(page: u16, bytes: &[u8]) -> Vec<u16> {
    let table = multi_table(page);
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        let b1 = bytes[i];
        let single = table.single[b1 as usize];
        if single != 0xFFFD {
            out.push(single);
            i += 1;
            continue;
        }
        if i + 1 >= bytes.len() {
            // an incomplete double byte char at the end of the input
            out.push(0xFFFD);
            i += 1;
            continue;
        }
        let b2 = bytes[i + 1];
        match table.decode_pair(b1, b2) {
            Some(unit) => {
                out.push(unit);
                i += 2;
            }
            None => {
                // `crMalformedOrUnmappable`: a malformed unit of length 1
                // unless the pair was one unmappable unit
                if !table.is_lead(b1) || table.is_lead(b2) || table.single[b2 as usize] != 0xFFFD {
                    out.push(0xFFFD);
                    i += 1;
                } else {
                    out.push(0xFFFD);
                    i += 2;
                }
            }
        }
    }
    out
}

fn encode_multi_byte(page: u16, s: &str) -> Vec<u8> {
    let table = multi_table(page);
    let encoding = multi_byte_encoding(page);
    let mut out = Vec::with_capacity(s.len() * 2);
    let mut encoder = encoding.new_encoder();
    let mut buf = [0u8; 8];
    for ch in s.chars() {
        let unit = ch as u32;
        if unit <= 0xFFFF {
            if let Some((bytes, len)) = table.enc_fix(unit as u16) {
                out.extend_from_slice(&bytes[..len]);
                continue;
            }
        }
        let mut utf8 = [0u8; 4];
        let one = ch.encode_utf8(&mut utf8);
        let (result, _read, written) =
            encoder.encode_from_utf8_without_replacement(one, &mut buf, true);
        out.extend_from_slice(&buf[..written]);
        if matches!(result, encoding_rs::EncoderResult::Unmappable(_)) {
            out.push(b'?');
        }
    }
    out
}

// ---------------------------------------------------------------------------
// IBM DBCS code pages
// ---------------------------------------------------------------------------

// The tables `java-src/CodePageGen.java bin` generated from the JDK charsets
// (see its documentation for the layout).  They are embedded zlib-compressed
// under `resources/z/` so the port needs neither a charset library nor a JVM
// to decode these pages.

/// SBCS/DBCS EBCDIC with SO/SI shifts (`DoubleByte.Decoder_EBCDIC`)
const DBCS_KIND_SHIFT: u8 = 0;
/// EBCDIC DBCS only, every two bytes are a double byte char
const DBCS_KIND_PAIR_ONLY: u8 = 1;
/// plain `DoubleByte.Decoder` (EUC style, no shifts)
const DBCS_KIND_PLAIN: u8 = 2;
/// `DoubleByte.Decoder_EUC_SIM` (SS2/SS3 are malformed, no shifts)
const DBCS_KIND_EUC_SIM: u8 = 3;
/// the custom EUC-TW style decoder of x-IBM964 (SS2 4 byte, SS3 invalid)
const DBCS_KIND_IBM964: u8 = 4;

/// the sentinel of an unmapped entry in the generated data
const DBCS_NONE: u16 = 0xFFFF;

/// the three G2 tables of x-IBM964, selected by the second byte
const DBCS_964_G2_SELECTORS: [u8; 3] = [0xA2, 0xAC, 0xAD];
const DBCS_964_G2_LEN: usize = 94 * 94;

/// one encoder mapping: the raw bytes a BMP unit encodes to.  The SO/SI
/// shifts of the stateful EBCDIC pages are not stored, the encoder state
/// machine adds them.
struct DbcsEnc {
    unit: u16,
    len: u8,
    bytes: [u8; 4],
}

/// One IBM DBCS code page: the JDK decode tables plus the exact encoder map.
struct DbcsPage {
    page: u16,
    kind: u8,
    name: &'static str,
    b2_min: u8,
    b2_max: u8,
    /// the bytes `CodingErrorAction.REPLACE` writes for an unmappable char
    repl: Vec<u8>,
    /// the JDK `b2cSB`: the decode of a single byte, `0xFFFF` if unmapped
    single: [u16; 256],
    /// the offset of a lead byte's row in `rows`, `-1` when it is no lead
    row_off: [i32; 256],
    /// the double byte rows, `b2_max - b2_min + 1` units each
    rows: Vec<u16>,
    /// the G2 tables of x-IBM964 (empty for every other page)
    g2: Vec<u16>,
    /// the encoder map, sorted by unit
    enc: Vec<DbcsEnc>,
}

impl DbcsPage {
    fn single(&self, b: u8) -> Option<u16> {
        let unit = self.single[b as usize];
        if unit == DBCS_NONE {
            None
        } else {
            Some(unit)
        }
    }

    /// `Decoder.isLeadingByte`: whether the byte starts a double byte char
    fn is_lead(&self, b: u8) -> bool {
        self.row_off[b as usize] >= 0
    }

    /// `b2c[b1][b2 - b2Min]`, `None` when the pair is not mapped (or out of
    /// the page's double byte range)
    fn pair(&self, b1: u8, b2: u8) -> Option<u16> {
        let off = self.row_off[b1 as usize];
        if off < 0 || b2 < self.b2_min || b2 > self.b2_max {
            return None;
        }
        let unit = self.rows[off as usize + (b2 - self.b2_min) as usize];
        if unit == DBCS_NONE {
            None
        } else {
            Some(unit)
        }
    }

    /// the G2 mapping of x-IBM964; `b2` and `b3` are in `0xA1..=0xFE`
    fn g2(&self, selector: u8, b2: u8, b3: u8) -> Option<u16> {
        let table = DBCS_964_G2_SELECTORS.iter().position(|&s| s == selector)?;
        let unit =
            self.g2[table * DBCS_964_G2_LEN + (b2 - 0xA1) as usize * 94 + (b3 - 0xA1) as usize];
        if unit == DBCS_NONE {
            None
        } else {
            Some(unit)
        }
    }

    /// the raw bytes of the encoder map entry of a BMP unit
    fn enc(&self, unit: u16) -> Option<&[u8]> {
        let i = self.enc.binary_search_by_key(&unit, |e| e.unit).ok()?;
        let e = &self.enc[i];
        Some(&e.bytes[..e.len as usize])
    }
}

struct DbcsData {
    pages: Vec<DbcsPage>,
}

/// Parse the embedded generated tables once, on the first IBM DBCS page use.
fn dbcs_data() -> &'static DbcsData {
    static DATA: std::sync::OnceLock<DbcsData> = std::sync::OnceLock::new();
    DATA.get_or_init(parse_dbcs_tables)
}

fn dbcs_table(page: u16) -> Option<&'static DbcsPage> {
    let data = dbcs_data();
    data.pages
        .binary_search_by_key(&page, |p| p.page)
        .ok()
        .map(|i| &data.pages[i])
}

struct DbcsReader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> DbcsReader<'a> {
    fn byte(&mut self) -> u8 {
        let v = self.data[self.pos];
        self.pos += 1;
        v
    }

    fn unit(&mut self) -> u16 {
        let v = u16::from_be_bytes([self.data[self.pos], self.data[self.pos + 1]]);
        self.pos += 2;
        v
    }

    fn int(&mut self) -> i32 {
        let v = i32::from_be_bytes([
            self.data[self.pos],
            self.data[self.pos + 1],
            self.data[self.pos + 2],
            self.data[self.pos + 3],
        ]);
        self.pos += 4;
        v
    }

    fn bytes(&mut self, len: usize) -> &'a [u8] {
        let v = &self.data[self.pos..self.pos + len];
        self.pos += len;
        v
    }
}

fn parse_dbcs_tables() -> DbcsData {
    let mut r = DbcsReader {
        data: crate::embedded::dbcs_table(),
        pos: 0,
    };
    assert_eq!(
        r.bytes(8),
        &b"JCECPT01"[..],
        "bad IBM DBCS table resource (magic)"
    );
    let count = r.int();
    let mut pages = Vec::with_capacity(count as usize);
    for _ in 0..count {
        let page = r.unit();
        let kind = r.byte();
        let name_len = r.unit() as usize;
        let name = std::str::from_utf8(r.bytes(name_len)).expect("dbcs table name");
        let b2_min = r.byte();
        let b2_max = r.byte();
        let repl_len = r.byte() as usize;
        let repl = r.bytes(repl_len).to_vec();
        let mut single = [0u16; 256];
        for unit in single.iter_mut() {
            *unit = r.unit();
        }
        let mut row_off = [0i32; 256];
        for off in row_off.iter_mut() {
            *off = r.int();
        }
        let row_count = r.int() as usize;
        let row_len = (b2_max - b2_min) as usize + 1;
        let mut rows = Vec::with_capacity(row_count * row_len);
        for _ in 0..row_count * row_len {
            rows.push(r.unit());
        }
        let g2_count = r.int() as usize;
        let mut g2 = Vec::with_capacity(g2_count * DBCS_964_G2_LEN);
        for _ in 0..g2_count * DBCS_964_G2_LEN {
            g2.push(r.unit());
        }
        let enc_count = r.int() as usize;
        let mut enc = Vec::with_capacity(enc_count);
        for _ in 0..enc_count {
            let unit = r.unit();
            let len = r.byte();
            let mut bytes = [0u8; 4];
            bytes[..len as usize].copy_from_slice(r.bytes(len as usize));
            enc.push(DbcsEnc { unit, len, bytes });
        }
        pages.push(DbcsPage {
            page,
            kind,
            name,
            b2_min,
            b2_max,
            repl,
            single,
            row_off,
            rows,
            g2,
            enc,
        });
    }
    assert_eq!(
        r.pos,
        crate::embedded::dbcs_table().len(),
        "trailing IBM DBCS table data"
    );
    DbcsData { pages }
}

/// `new String(bytes, charset)` for an IBM DBCS page: the JDK's `ArrayDecoder`
/// fast paths (`DoubleByte.Decoder`, `Decoder_EBCDIC`, `Decoder_DBCSONLY`,
/// `Decoder_EUC_SIM`) and, for x-IBM964, the plain `CharsetDecoder` loop with
/// `CodingErrorAction.REPLACE`.  Every malformed/unmappable unit becomes one
/// U+FFFD, with the byte counts the JDK uses.
fn decode_dbcs(page: u16, bytes: &[u8]) -> Vec<u16> {
    let table = dbcs_table(page).expect("dbcs charset without table");
    let mut out = Vec::with_capacity(bytes.len());
    match table.kind {
        // `DoubleByte.Decoder_EBCDIC.decode(byte[], int, int, char[])`
        DBCS_KIND_SHIFT => {
            let mut dbcs = false;
            let mut i = 0;
            while i < bytes.len() {
                let b1 = bytes[i];
                if b1 == 0x0E {
                    if !dbcs {
                        dbcs = true;
                    } else {
                        out.push(0xFFFD);
                    }
                    i += 1;
                } else if b1 == 0x0F {
                    if dbcs {
                        dbcs = false;
                    } else {
                        out.push(0xFFFD);
                    }
                    i += 1;
                } else if !dbcs {
                    out.push(table.single(b1).unwrap_or(0xFFFD));
                    i += 1;
                } else if i + 1 >= bytes.len() {
                    out.push(0xFFFD);
                    i += 1;
                } else {
                    out.push(table.pair(b1, bytes[i + 1]).unwrap_or(0xFFFD));
                    i += 2;
                }
            }
        }
        // `Decoder_DBCSONLY` inherits the base `Decoder.decode`, whose single
        // byte table is all unmappable: every two bytes are one char and an
        // invalid pair is one unmappable unit of length two
        DBCS_KIND_PAIR_ONLY => {
            let mut i = 0;
            while i < bytes.len() {
                if i + 1 < bytes.len() {
                    out.push(table.pair(bytes[i], bytes[i + 1]).unwrap_or(0xFFFD));
                    i += 2;
                } else {
                    out.push(0xFFFD);
                    i += 1;
                }
            }
        }
        // the base `DoubleByte.Decoder.decode`: a malformed pair is length one
        // when the second byte could start a char itself, else length two
        DBCS_KIND_PLAIN => {
            let mut i = 0;
            while i < bytes.len() {
                let b1 = bytes[i];
                i += 1;
                let mut decoded = table.single(b1);
                if decoded.is_none() && i < bytes.len() {
                    let b2 = bytes[i];
                    i += 1;
                    match table.pair(b1, b2) {
                        Some(unit) => decoded = Some(unit),
                        None => {
                            if !table.is_lead(b1) || table.is_lead(b2) || table.single(b2).is_some()
                            {
                                i -= 1;
                            }
                        }
                    }
                }
                out.push(decoded.unwrap_or(0xFFFD));
            }
        }
        // `Decoder_EUC_SIM`: like the base decoder, but SS2/SS3 are malformed
        // units of length one instead of a two byte attempt
        DBCS_KIND_EUC_SIM => {
            let mut i = 0;
            while i < bytes.len() {
                let b1 = bytes[i];
                i += 1;
                let mut decoded = table.single(b1);
                if decoded.is_none() && i < bytes.len() {
                    let b2 = bytes[i];
                    i += 1;
                    match table.pair(b1, b2) {
                        Some(unit) => decoded = Some(unit),
                        None => {
                            if b1 == 0x8E || b1 == 0x8F {
                                i -= 1;
                            }
                        }
                    }
                }
                out.push(decoded.unwrap_or(0xFFFD));
            }
        }
        // x-IBM964's custom decoder: G1 pairs behind a lead byte, G2 behind
        // SS2 + selector, SS3 invalid; an incomplete run at the end of the
        // input is one malformed unit covering all remaining bytes
        DBCS_KIND_IBM964 => {
            let mut i = 0;
            while i < bytes.len() {
                let b1 = bytes[i];
                if b1 == 0x8E {
                    if bytes.len() - i < 4 {
                        out.push(0xFFFD);
                        break;
                    }
                    let selector = bytes[i + 1];
                    match DBCS_964_G2_SELECTORS.iter().position(|&s| s == selector) {
                        Some(_) => {}
                        None => {
                            out.push(0xFFFD);
                            i += 2;
                            continue;
                        }
                    }
                    let b2 = bytes[i + 2];
                    if !(0xA1..=0xFE).contains(&b2) {
                        out.push(0xFFFD);
                        i += 3;
                        continue;
                    }
                    let b3 = bytes[i + 3];
                    if !(0xA1..=0xFE).contains(&b3) {
                        out.push(0xFFFD);
                        i += 4;
                        continue;
                    }
                    out.push(table.g2(selector, b2, b3).unwrap_or(0xFFFD));
                    i += 4;
                } else if b1 == 0x8F {
                    out.push(0xFFFD);
                    i += 1;
                } else if b1 <= 0x9F {
                    out.push(table.single(b1).unwrap_or(0xFFFD));
                    i += 1;
                } else if !(0xA1..=0xFE).contains(&b1) {
                    out.push(0xFFFD);
                    i += 1;
                } else if bytes.len() - i < 2 {
                    out.push(0xFFFD);
                    break;
                } else {
                    let b2 = bytes[i + 1];
                    if !(0xA1..=0xFE).contains(&b2) {
                        out.push(0xFFFD);
                        i += 2;
                    } else {
                        out.push(table.pair(b1, b2).unwrap_or(0xFFFD));
                        i += 2;
                    }
                }
            }
        }
        kind => panic!("unknown IBM DBCS decoder kind {}", kind),
    }
    out
}

/// `String.getBytes(charset)` for an IBM DBCS page.
fn encode_dbcs(page: u16, s: &str) -> Vec<u8> {
    let table = dbcs_table(page).expect("dbcs charset without table");
    if table.kind == DBCS_KIND_SHIFT {
        return encode_dbcs_shift(table, s);
    }
    let mut out = Vec::with_capacity(s.len());
    for ch in s.chars() {
        match u16::try_from(ch as u32).ok().and_then(|u| table.enc(u)) {
            Some(bytes) => out.extend_from_slice(bytes),
            None => out.extend_from_slice(&table.repl),
        }
    }
    out
}

/// `Encoder_EBCDIC`'s state machine: a shift out before the first double byte
/// char, a shift in before a single byte char, and one at the end when the
/// output stopped in the double byte state.  An unmappable char writes the
/// replacement byte without changing the state (as the JDK does).
fn encode_dbcs_shift(table: &DbcsPage, s: &str) -> Vec<u8> {
    let mut out = Vec::with_capacity(s.len() * 2);
    let mut dbcs = false;
    for ch in s.chars() {
        let raw = u16::try_from(ch as u32).ok().and_then(|u| table.enc(u));
        match raw {
            None => out.extend_from_slice(&table.repl),
            Some(bytes) if bytes.len() == 2 => {
                if !dbcs {
                    out.push(0x0E);
                    dbcs = true;
                }
                out.extend_from_slice(bytes);
            }
            Some(bytes) => {
                if dbcs {
                    out.push(0x0F);
                    dbcs = false;
                }
                out.extend_from_slice(bytes);
            }
        }
    }
    if dbcs {
        out.push(0x0F);
    }
    out
}

/// `ColumnImpl.SortOrder`
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct SortOrder {
    pub value: i16,
    pub variant: i16,
    pub version: i16,
}

impl SortOrder {
    pub const GENERAL_97: SortOrder = SortOrder {
        value: 1033,
        variant: 0,
        version: -1,
    };
    pub const GENERAL_LEGACY: SortOrder = SortOrder {
        value: 1033,
        variant: 0,
        version: 0,
    };
    pub const GENERAL: SortOrder = SortOrder {
        value: 1033,
        variant: 0,
        version: 1,
    };

    /// `ColumnImpl.SortOrder.getSortId()`: the ms access sort id, which names
    /// the collation on its own.
    ///
    /// A jet 3 sort order has no version byte and reports `-1`, so it has no
    /// sort id: Java throws
    /// `IllegalStateException("sort order " + this + " has no sort id")`, and
    /// this method returns that `IllegalStateException` as
    /// [`Error::IllegalState`].
    pub fn get_sort_id(&self) -> crate::error::Result<i32> {
        if self.version < 0 {
            return Err(crate::error::Error::IllegalState(format!(
                "sort order {} has no sort id",
                self
            )));
        }
        Ok(((self.version as i32) << 24)
            | (((self.variant as i32) & 0xFF) << 16)
            | ((self.value as i32) & 0xFFFF))
    }
}

/// `SortOrder.toString()`: `SortOrder[<sort id or (value,variant,version)>,
/// <locale name>]` (the locale name is left off for an LCID jackcess does not
/// know, exactly like `LocaleUtil.getInfo` returning null).
impl std::fmt::Display for SortOrder {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let value = if self.version >= 0 {
            // Java's `String.format("0x%08X", getSortId())`
            format!("0x{:08X}", self.get_sort_id().unwrap_or(0))
        } else {
            format!("{}({},{})", self.value, self.variant, self.version)
        };
        let value = match lcid_name(self.value as i32) {
            Some(name) => format!("{}, {}", value, name),
            None => value,
        };
        write!(f, "SortOrder[{}]", value)
    }
}

